def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        n = int(input_data)
        # Each of the 3 characters can be any digit from 1 to N
        # Total combinations = N * N * N = N^3
        print(n ** 3)
    except Exception:
        pass

if __name__ == "__main__":
    solve()

